-- ============================================================
-- SIENGE_OBRA -- espelho estatico do centro de custo do Sienge, so
-- pra alimentar o painel "Onde estao as obras" no dashboard.
--
-- NAO e' a mesma coisa que a tabela `obra`: aquela e' o que o time
-- decidiu acompanhar aqui dentro; esta e' o HISTORICO INTEIRO da
-- empresa (todo centro de custo >= 1000 com cidade/UF cadastrados no
-- Sienge, voltando ate' 2018) -- so pra saber onde cada obra fica e
-- montar o mapa por estado/cidade. Nao tem categorias, nao tem
-- planilha, nao tem nada do trabalho -- so' localizacao.
--
-- Estatico de proposito: export manual do Sienge, sem API direta
-- ainda. Atualizar e' reexportar e rodar este arquivo de novo (o
-- upsert por codigo nao duplica).
-- ============================================================

create table if not exists sienge_obra (
  codigo   text primary key,
  nome     text not null,
  cidade   text not null,
  estado   text not null,
  endereco_completo text,
  atualizado_em timestamptz default now()
);

alter table sienge_obra enable row level security;

drop policy if exists "leitura time (autenticados)" on sienge_obra;
create policy "leitura time (autenticados)" on sienge_obra
  for select
  to authenticated
  using (true);

-- Import roda por quem tem a chave de servico (Supabase SQL Editor) --
-- o app so' LE esta tabela, nunca escreve nela.

on conflict (codigo) do update set
  nome = excluded.nome, cidade = excluded.cidade, estado = excluded.estado,
  endereco_completo = excluded.endereco_completo, atualizado_em = now();
